import{_ as e,o,c as r,a1 as i}from"./chunks/framework.COskihg7.js";const u=JSON.parse('{"title":"Features","description":"","frontmatter":{},"headers":[],"relativePath":"features.md","filePath":"features.md"}'),n={name:"features.md"};function a(s,t,l,d,c,h){return o(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h1><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>Hotspot Bypass VPN uses a clever two-step approach to bypass carrier tethering restrictions:</p><ol><li><strong>Wi-Fi Direct</strong> — Instead of using the system&#39;s mobile hotspot (which carriers can detect), the app creates a Wi-Fi Direct (P2P) group. This appears to the carrier as regular phone-to-phone communication.</li><li><strong>SOCKS5 Proxy</strong> — A high-performance SOCKS5 proxy server runs on the host phone. Client devices connect to the Wi-Fi Direct network and route all traffic through this proxy.</li></ol><p>From the carrier&#39;s perspective, all traffic originates directly from the host phone&#39;s cellular connection — <strong>not</strong> from a tethered device.</p><hr><h2 id="host-mode" tabindex="-1">Host Mode <a class="header-anchor" href="#host-mode" aria-label="Permalink to &quot;Host Mode&quot;">​</a></h2><p>Share your phone&#39;s cellular data with other devices.</p><ul><li>Creates a Wi-Fi Direct network with SSID <code>DIRECT-HotspotBypass</code></li><li>Custom password protection (default: <code>87654321</code>)</li><li>Band selection: 2.4GHz (longer range) or 5GHz (lower latency)</li><li>Built-in SOCKS5 proxy server (TCP + UDP) on port 8080</li><li>One-tap copy of connection info (SSID, password, proxy IP, port)</li><li>Foreground service keeps connection alive with screen off</li></ul><h2 id="client-mode" tabindex="-1">Client Mode <a class="header-anchor" href="#client-mode" aria-label="Permalink to &quot;Client Mode&quot;">​</a></h2><p>Connect to another phone running Host mode and tunnel all your traffic.</p><ul><li>Uses Android VpnService with tun2socks engine for full traffic interception</li><li>All apps, all protocols — everything goes through the proxy</li><li>Dedicated reconnect button to restart the tunnel</li><li>Works great for gaming, streaming, and browsing</li></ul><h2 id="windows-desktop-client" tabindex="-1">Windows Desktop Client <a class="header-anchor" href="#windows-desktop-client" aria-label="Permalink to &quot;Windows Desktop Client&quot;">​</a></h2><p>A full-featured Python application for Windows laptops.</p><ul><li><strong>TUN Virtual Adapter</strong> — Creates a virtual network card that routes 100% of Windows traffic through the phone&#39;s SOCKS5 proxy</li><li><strong>Automatic Setup</strong> — Downloads tun2socks and wintun dependencies automatically on first run</li><li><strong>Admin Rights Handling</strong> — Automatically elevates privileges when needed for network configuration</li><li><strong>GUI Dashboard</strong> — Clean interface with real-time status, logs, and controls</li><li><strong>Console/Device Bridge</strong> — Can share the VPN connection onward via Windows Mobile Hotspot + ICS</li></ul><h2 id="non-app-device-support" tabindex="-1">Non-App Device Support <a class="header-anchor" href="#non-app-device-support" aria-label="Permalink to &quot;Non-App Device Support&quot;">​</a></h2><p>Connect devices that cannot run the app directly:</p><table tabindex="0"><thead><tr><th>Device</th><th>Method</th></tr></thead><tbody><tr><td><strong>PS4 / PS5</strong></td><td>Bridge via Windows ICS</td></tr><tr><td><strong>Xbox One / Series X|S</strong></td><td>Bridge via Windows ICS</td></tr><tr><td><strong>Nintendo Switch</strong></td><td>Bridge via Windows ICS</td></tr><tr><td><strong>MacBook</strong></td><td>Bridge via Windows ICS (full gaming support)</td></tr><tr><td><strong>Smart TVs</strong></td><td>Bridge via Windows ICS</td></tr></tbody></table><h2 id="connection-persistence" tabindex="-1">Connection Persistence <a class="header-anchor" href="#connection-persistence" aria-label="Permalink to &quot;Connection Persistence&quot;">​</a></h2><ul><li><strong>Foreground Service</strong> — Runs as a high-priority foreground service to prevent Android from killing it</li><li><strong>WakeLock + WifiLock</strong> — Prevents CPU and Wi-Fi sleep</li><li><strong>AlarmManager Restart</strong> — Auto-restarts the service if it stops unexpectedly</li><li><strong>Boot Receiver</strong> — Can auto-start on device boot</li></ul><h2 id="security-privacy" tabindex="-1">Security &amp; Privacy <a class="header-anchor" href="#security-privacy" aria-label="Permalink to &quot;Security &amp; Privacy&quot;">​</a></h2><ul><li><strong>No Root Required</strong> — Uses only standard Android APIs</li><li><strong>Local Proxy Only</strong> — The SOCKS5 proxy binds to the Wi-Fi Direct interface only</li><li><strong>MIT License</strong> — Fully open source, inspect the code yourself</li></ul>',22)])])}const g=e(n,[["render",a]]);export{u as __pageData,g as default};
